      "code": "OUTCOME_DERIVED_LABEL",
      "text": "If 'shaper' or 'heavy' classifications are derived from outcomes or aggregate statistics that are themselves influenced by the 'travel' effect, it could introduce circularity."
    }
  ],
  "predicted_outcome": {
    "supported": 0.1,
    "rejected": 0.2,
    "untestable": 0.5,
    "artifact": 0.1,
    "uncertain": 0.1
  },
